QUIZ.registrar({
  id:"8ano-geografia-4bim", ano:"8º ano", materia:"Geografia", emoji:"🌎",
  bimestre:"4º bimestre", tema:"América Latina: economia, indústria e comércio",
  qtdAquecimento:8, qtdTeste:12,
  rodadas:[
    { id:"r1", emoji:"🌽", nome:"Rodada 1 — Agropecuária no México e na América Central",
      desc:"O milho dos astecas, as plantations e a herança da escravidão.",
      resumo:["A AMÉRICA LATINA agrupa a maior parte dos países da América, de Norte a Sul, com as EXCEÇÕES de Estados Unidos e Canadá.","Desde a colonização, as atividades agropecuárias têm grande importância econômica nesses países, e até hoje o SETOR PRIMÁRIO mantém peso significativo em muitos deles. A região abriga grande DIVERSIDADE de modelos produtivos no setor agropecuário.","MÉXICO: a agropecuária abastece principalmente o MERCADO INTERNO, ainda que haja produtos destinados à exportação.","Dificuldades naturais do México: mais de 60% do território é ÁRIDO ou SEMIÁRIDO e mais de 30% do relevo é MONTANHOSO, restando poucas terras com condições favoráveis ao cultivo. Mesmo já tendo havido reforma agrária, a CONCENTRAÇÃO FUNDIÁRIA continua sendo um problema: as grandes propriedades dominam as melhores terras.","Em 2023, o MILHO ocupava 34% das terras agrícolas usadas nas produções anuais e correspondia a 87% da produção de grãos do México.","CONUCO: técnica que consiste em plantar o milho associado à mandioca, à batata e à batata-doce. Hoje a lavoura do milho também aparece associada à do feijão e à do tomate.","Atenção a um deslize da apostila: ela atribui o conuco aos ASTECAS. Na verdade o conuco é dos povos ARUAQUES/TAÍNOS do Caribe e do norte da América do Sul. As técnicas agrícolas astecas são a CHINAMPA (as ilhas de cultivo nos lagos) e a MILPA.","Entre as produções PERENES (que não são renovadas anualmente) destacam-se o CAFÉ e a LARANJA. A CANA-DE-AÇÚCAR é sazonal e associada ao modelo de PLANTATION — todas voltadas à exportação.","Nas regiões CENTRO e SUL do México predominam pequenas propriedades de AGRICULTURA DE SUBSISTÊNCIA: mão de obra familiar, pouca tecnologia, produção para o próprio consumo, e apenas o EXCEDENTE é vendido em feiras e mercados locais. É praticada sobretudo por povos indígenas, que produzem principalmente MILHO, base alimentar da população.","AMÉRICA CENTRAL: a agropecuária tem grande importância econômica apesar dos obstáculos naturais — montanhas, pântanos e áreas semiáridas — que reduzem o espaço disponível. Mesmo assim, o modelo dominante é o de PLANTATION.","O plantation foi introduzido na região a partir do SÉCULO XVI, no início da colonização, atendendo aos interesses dos nobres europeus e dos comerciantes e colonos. No FINAL DO SÉCULO XIX, com as independências e a libertação dos escravizados, o trabalho continuou braçal, mas passou a usar mão de obra ASSALARIADA TEMPORÁRIA, em geral abundante e barata.","Há elevada participação do CAPITAL ESTRANGEIRO na propriedade da terra, no beneficiamento e no controle do comércio de exportação, quase sempre por meio de empresas agroindustriais e bancos transnacionais."],
      questoes:[
        {p:"Quais países da América NÃO fazem parte da América Latina?", alt:["Estados Unidos e Canadá","México e Guatemala","Brasil e Argentina","Cuba e Haiti"], c:0, exp:"A América Latina agrupa a maior parte dos países da América, de Norte a Sul, com essas duas exceções."},
        {p:"A agropecuária mexicana se destina principalmente a quê?", alt:["Ao abastecimento do mercado interno","Exclusivamente à exportação para os Estados Unidos","À produção de biocombustíveis","À alimentação de rebanhos europeus"], c:0, exp:"Existem produtos voltados à exportação, mas o grosso da produção abastece o próprio país.", err:{1:"A exportação existe, mas não é o destino principal da produção mexicana."}},
        {t:"num", p:"Mais de quantos por cento do território mexicano é árido ou semiárido? (só o número)", r:"60", aceita:["60","60%"], exp:"Mais de 60% do território é árido ou semiárido — e mais de 30% do relevo é montanhoso."},
        {p:"Além da aridez, que outra condição natural dificulta a agropecuária no México?", alt:["Mais de 30% do relevo é montanhoso","O território é coberto por florestas tropicais","O solo é permanentemente congelado","O país não tem acesso ao mar"], c:0, exp:"Aridez e montanhas juntas deixam poucas terras com condições naturais favoráveis ao cultivo.", err:{3:"O México tem extenso litoral — são 11 mil km voltados à pesca."}},
        {p:"Que problema fundiário o México mantém, mesmo após ter realizado reforma agrária?", alt:["A concentração fundiária: as grandes propriedades dominam as melhores terras","A ausência total de propriedade privada da terra","O excesso de pequenas propriedades improdutivas","A proibição de estrangeiros comprarem terras"], c:0, exp:"Diversos governos tentaram resolver a distribuição de terras, mas a concentração continua."},
        {t:"num", p:"Em 2023, que porcentagem da produção de grãos do México correspondia ao milho? (só o número)", r:"87", aceita:["87","87%"], exp:"87% da produção de grãos — e o milho ocupava 34% das terras agrícolas usadas nas produções anuais."},
        {p:"Em que consiste a técnica do conuco, citada na apostila?", alt:["Plantar milho associado a mandioca, batata e batata-doce","Queimar a vegetação antes de plantar","Irrigar as lavouras com canais subterrâneos","Criar gado junto com a lavoura de café"], c:0, exp:"É um consórcio de culturas. Hoje a lavoura do milho também aparece associada à do feijão e à do tomate."},
        {p:"Quais culturas mexicanas são consideradas PERENES?", alt:["Café e laranja","Milho e feijão","Tomate e abóbora","Trigo e cevada"], c:0, exp:"Perenes são as que não precisam ser replantadas a cada ano. A cana-de-açúcar, por sua vez, é sazonal e ligada ao plantation."},
        {p:"Como funciona a agricultura de subsistência nas regiões centro e sul do México?", alt:["Mão de obra familiar, pouca tecnologia e produção para o próprio consumo","Grandes propriedades mecanizadas voltadas à exportação","Produção estatal distribuída em cooperativas","Cultivo em estufas com alta tecnologia"], c:0, exp:"Apenas a parte excedente é comercializada, geralmente em feiras e mercados locais."},
        {p:"Quem pratica sobretudo a agricultura de subsistência no México, e que produto cultiva?", alt:["Povos indígenas, que produzem principalmente milho","Imigrantes europeus, que produzem trigo","Empresas estrangeiras, que produzem soja","Cooperativas urbanas, que produzem hortaliças"], c:0, exp:"O milho é a base alimentar da população mexicana — por isso está no centro tanto da subsistência quanto da produção comercial."},
        {p:"Qual é o modelo de produção DOMINANTE na América Central?", alt:["O plantation","A agricultura de subsistência","A pecuária intensiva","A agricultura mediterrânea"], c:0, exp:"Mesmo com montanhas, pântanos e áreas semiáridas reduzindo o espaço disponível, o plantation predomina.", err:{3:"A agricultura mediterrânea é característica do Chile, não da América Central."}},
        {t:"num", p:"Em que século o modelo de plantation foi introduzido na América Central? (responda com o número, ex.: 18)", r:"16", aceita:["16","XVI","século XVI","seculo 16"], exp:"Século XVI, no início da colonização — atendendo aos interesses dos nobres europeus e dos comerciantes e colonos que ocupavam a região."},
        {p:"O que mudou nas plantations da América Central no final do século XIX?", alt:["O trabalho continuou braçal, mas passou a usar mão de obra assalariada temporária","As plantations foram substituídas por indústrias","A terra foi dividida entre os ex-escravizados","O cultivo passou a ser totalmente mecanizado"], c:0, exp:"As independências vieram acompanhadas da libertação dos escravizados — e a mão de obra assalariada temporária era, em geral, abundante e barata."},
        {p:"Que obstáculos naturais a agropecuária enfrenta na América Central?", alt:["Montanhas, pântanos e áreas semiáridas","Geadas e neve durante todo o ano","Desertos de areia que cobrem a região inteira","Ausência completa de rios"], c:0, exp:"Esses obstáculos reduzem o espaço disponível para a produção agrícola e se agravam nas porções insulares da região."},
        {p:"Qual é a situação da propriedade da terra e do comércio agrícola na América Central?", alt:["Há elevada participação do capital estrangeiro, via empresas agroindustriais e bancos transnacionais","A terra é toda estatal e o comércio, controlado pelos governos","Pequenos produtores locais controlam a exportação","Não existe comércio de exportação na região"], c:0, exp:"O capital estrangeiro aparece na propriedade da terra, no beneficiamento da produção e no controle do comércio de exportação."},
        {p:"Segundo a tabela da apostila, em qual país da América Central a agropecuária e o extrativismo têm MAIOR participação no PIB?", alt:["Haiti, com 20,3%","Guatemala, com 9,3%","Cuba, com 0,8%","Panamá, com 2,6%"], c:0, exp:"Atenção à diferença: a Guatemala tem o maior VALOR de produção da tabela, mas é no Haiti que o setor mais pesa no PIB — 20,3%.", err:{1:"A Guatemala lidera em valor absoluto, não em participação no PIB."}}
      ]},
    { id:"r2", emoji:"🦙", nome:"Rodada 2 — Agropecuária na América do Sul",
      desc:"Guianas, América Andina e América Platina: quatro sub-regiões, quatro realidades.",
      resumo:["A América do Sul pode ser agrupada em QUATRO sub-regiões: o BRASIL, a AMÉRICA PLATINA (Argentina, Paraguai e Uruguai), a AMÉRICA ANDINA (Venezuela, Colômbia, Equador, Peru, Bolívia e Chile) e as GUIANAS (Guiana, Suriname e Guiana Francesa).","GUIANAS: diferem do resto da América Latina porque foram colonizadas por HOLANDA, INGLATERRA e FRANÇA, e não por Espanha ou Portugal. A GUIANA FRANCESA não é um país independente: é um DEPARTAMENTO ULTRAMARINO da França.","Cerca de 90% dos agricultores da Guiana Francesa se dedicam à agricultura de SUBSISTÊNCIA, embora existam lavouras comerciais de cana-de-açúcar. No SURINAME a situação é parecida: há arroz e banana para exportação, mas a maior parte da agricultura é de subsistência.","A GUIANA é o único país da região em que o INGLÊS é UMA DAS línguas oficiais (assim como na Jamaica e nas Bahamas, na América Central insular). Foi posse holandesa no século XVII e dominada pelo Reino Unido entre 1812 e 1966, dedicada à produção açucareira em PLANTATIONS.","Suriname em números: área total de pouco mais de 163 000 km², MENOR que o estado do Acre; apenas 0,5% do território é usado para agricultura; cerca de 94% é coberto por florestas tropicais; e os 613 000 habitantes se concentram nas áreas litorâneas.","AMÉRICA ANDINA: formada pelos países atravessados pela CORDILHEIRA DOS ANDES. A agropecuária de subsistência, embora em redução, ainda é comum na porção andina de Peru, Bolívia, Colômbia e Equador, onde se criam LHAMAS e se cultivam MILHO e BATATA, em pequenas propriedades familiares, com técnicas rudimentares, baixa produtividade e nas terras menos férteis.","Destaques das plantations andinas: a COLÔMBIA é o SEGUNDO maior exportador de café e o EQUADOR é o QUARTO maior produtor de bananas do mundo.","CHILE: as condições climáticas favorecem a AGRICULTURA MEDITERRÂNEA. As baixas temperaturas do inverno e as poucas chuvas favorecem a produção de UVAS para vinho; o vale central chileno é reconhecido internacionalmente pela qualidade dos vinhos. Também se cultivam azeitonas (para azeite), trigo e batata.","A CORRENTE DE HUMBOLDT se origina na Antártica e segue para o NORTE pelo litoral do Chile e do Peru. Ela carrega grandes quantidades de PLÂNCTON, o que atrai peixes e favorece a pesca nesses países.","AMÉRICA PLATINA: o nome vem do RIO DA PRATA, formado pela conjunção dos rios PARANÁ e URUGUAI. Em extensas áreas da Argentina e do Uruguai há agroindústria ligada à pecuária bovina INTENSIVA (leite e carnes selecionadas), entre as mais modernas da América do Sul, com destaque para trigo, soja e milho, elevada mecanização e alta produtividade.","A ARGENTINA é o país onde, proporcionalmente à população, mais se consome carne no mundo: 48,5 kg/ano por pessoa em 2021, contra 16,3 do Uruguai, 14,9 do Paraguai e 9,4 da média mundial.","Região dos PAMPAS (Uruguai e leste da Argentina): solos férteis, relevo plano, vegetação rasteira, clima ameno e úmido.","PARAGUAI: a agropecuária representa quase 20% do PIB e emprega quase METADE da população. Pecuária extensiva e soja são as principais atividades, e o país é o QUARTO maior exportador de soja, atrás de Brasil, Estados Unidos e Argentina."],
      questoes:[
        {p:"Em quais quatro sub-regiões a América do Sul costuma ser agrupada?", alt:["Brasil, América Platina, América Andina e Guianas","Norte, Sul, Leste e Oeste","Caribe, Andes, Amazônia e Pampa","Cone Sul, Amazônia, Guianas e Caribe"], c:0, exp:"O agrupamento considera características históricas, culturais e econômicas semelhantes."},
        {p:"Quais países formam a América Platina?", alt:["Argentina, Paraguai e Uruguai","Chile, Peru e Bolívia","Brasil, Argentina e Chile","Colômbia, Equador e Venezuela"], c:0, exp:"O nome vem do rio da Prata, formado pela conjunção dos rios Paraná e Uruguai, fronteiras naturais desses três países."},
        {p:"Por que as Guianas diferem historicamente do resto da América Latina?", alt:["Foram colonizadas por Holanda, Inglaterra e França","Nunca foram colonizadas por europeus","Foram colonizadas apenas por Portugal","Tornaram-se independentes ainda no século XVI"], c:0, exp:"Enquanto a maior parte da região passou por colonização espanhola — e o Brasil, portuguesa — essas três passaram por outros colonizadores europeus."},
        {p:"Qual dessas três não é um país independente?", alt:["A Guiana Francesa, que é um departamento ultramarino da França","A Guiana, que é território do Reino Unido","O Suriname, que pertence à Holanda","Todas as três são independentes"], c:0, exp:"A Guiana Francesa é parte da França. O Suriname é ex-colônia holandesa e a Guiana, ex-colônia britânica, mas ambos são independentes."},
        {p:"Em qual país da região o inglês é uma das línguas oficiais, segundo a apostila?", alt:["Guiana","Suriname","Guiana Francesa","Peru"], c:0, exp:"A Guiana foi dominada pelo Reino Unido entre 1812 e 1966. Jamaica e Bahamas, na América Central insular, também têm o inglês entre suas línguas oficiais.", err:{1:"O Suriname foi colônia holandesa."}},
        {t:"num", p:"Qual porcentagem do território do Suriname é usada para agricultura? (use vírgula, ex.: 1,5)", r:"0,5", aceita:["0,5","0.5","0,5%"], exp:"Apenas 0,5% — o que totaliza 815 km², área equivalente à do pequeno município de Coronel Murta, em Minas Gerais. Cerca de 94% do país é coberto por florestas tropicais."},
        {p:"Comparado ao Brasil, qual é o tamanho do Suriname?", alt:["Seu território é menor que o do estado do Acre","É maior que a região Sul inteira","Tem quase o tamanho do estado de São Paulo","É o maior país da América do Sul depois do Brasil"], c:0, exp:"Pouco mais de 163 000 km², com 613 000 habitantes concentrados nas áreas litorâneas."},
        {p:"O que caracteriza a América Andina?", alt:["É formada pelos países cujo território é atravessado pela cordilheira dos Andes","Reúne os países banhados pelo rio da Prata","Agrupa as ilhas do mar do Caribe","É a região das antigas colônias inglesas"], c:0, exp:"Chile, Peru, Equador, Bolívia, Venezuela e Colômbia compartilham o trajeto da cordilheira e algumas características históricas, culturais e econômicas."},
        {p:"O que se cria e se cultiva na agropecuária de subsistência da porção andina?", alt:["Lhamas, milho e batata","Gado bovino, soja e trigo","Ovelhas, uvas e azeitonas","Búfalos, arroz e cana-de-açúcar"], c:0, exp:"O cultivo é feito em pequenas propriedades familiares, com técnicas rudimentares de baixa produtividade, nas terras menos férteis. Esses produtos têm importância apenas regional."},
        {p:"A Colômbia se destaca mundialmente como:", alt:["Segundo maior exportador de café","Maior produtor de bananas","Maior exportador de soja","Segundo maior produtor de vinho"], c:0, exp:"Pela presença das plantations. A apostila chama o Equador de quarto maior PRODUTOR de bananas; na verdade ele é o maior EXPORTADOR do mundo, e como produtor fica mais atrás, depois de Índia, China, Indonésia e Brasil."},
        {p:"Por que o Chile desenvolveu a agricultura mediterrânea?", alt:["Porque suas condições climáticas lembram as dos países banhados pelo mar Mediterrâneo","Porque recebeu imigrantes italianos e gregos","Porque a Cordilheira dos Andes bloqueia os ventos frios","Porque o governo proibiu outros tipos de cultivo"], c:0, exp:"Baixas temperaturas no inverno e poucas chuvas favorecem a uva para vinho. Também se cultivam azeitonas, trigo e batata.", err:{1:"O livro atribui a agricultura mediterrânea ao clima, não à imigração."}},
        {p:"Qual região chilena é internacionalmente reconhecida pela qualidade dos vinhos?", alt:["O vale central","O deserto do Atacama","A Patagônia","A ilha de Chiloé"], c:0, exp:"As baixas temperaturas do inverno e a ocorrência de poucas chuvas favorecem a produção de uvas para a fabricação de vinhos."},
        {p:"Qual é o efeito da corrente marítima de Humboldt no litoral do Chile e do Peru?", alt:["Carrega plâncton, atrai peixes e favorece a pesca","Aquece as águas e favorece o turismo","Provoca chuvas intensas o ano inteiro","Dificulta a navegação de grandes navios"], c:0, exp:"A corrente se origina na Antártica e segue em direção ao Norte pelo litoral desses dois países."},
        {p:"Que tipo de pecuária predomina nas áreas modernas da Argentina e do Uruguai?", alt:["Pecuária bovina intensiva, com leite e carnes selecionadas","Pecuária extensiva de baixa produtividade","Criação de lhamas e alpacas","Criação de caprinos em áreas semiáridas"], c:0, exp:"São áreas entre as mais modernas da América do Sul, que se sobressaem também na produção de trigo, soja e milho, com elevada mecanização e alta produtividade."},
        {t:"num", p:"Quantos quilos de carne por ano, per capita, a Argentina consumiu em 2021? (use vírgula, ex.: 12,3)", r:"48,5", aceita:["48,5","48.5","48,5 kg"], exp:"48,5 kg/ano — contra 16,3 do Uruguai, 14,9 do Paraguai e 9,4 da média mundial. A Argentina é o país onde, proporcionalmente à população, mais se consome carne no mundo."},
        {p:"O que favorece as atividades rurais na região dos Pampas?", alt:["Solos férteis, relevo plano, vegetação rasteira e clima ameno e úmido","Solos vulcânicos e altitude elevada","Chuvas torrenciais e florestas densas","Clima desértico e irrigação artificial"], c:0, exp:"Os Pampas abrangem o Uruguai e o leste da Argentina."},
        {p:"Qual é o peso da agropecuária na economia do Paraguai?", alt:["Representa quase 20% do PIB e emprega quase metade da população","Representa menos de 5% do PIB","É irrelevante frente à indústria","Emprega apenas trabalhadores estrangeiros"], c:0, exp:"Pecuária extensiva e produção de soja são as principais atividades do setor no país."},
        {p:"O Paraguai é o quarto maior exportador mundial de qual produto?", alt:["Soja","Café","Carne bovina","Trigo"], c:0, exp:"Fica atrás somente de Brasil, Estados Unidos e Argentina."}
      ]},
    { id:"r3", emoji:"⛏️", nome:"Rodada 3 — Produção mineral e energética",
      desc:"Cobre, ferro, prata, lítio — e por que exportar matéria-prima rende pouco.",
      resumo:["Os recursos minerais são extraídos do subsolo e, depois de beneficiados, viram MATÉRIA-PRIMA para bens de consumo, construção civil e geração de energia (petróleo e carvão mineral).","A produção mineral, como a agricultura, faz parte do SETOR PRIMÁRIO. Mesmo sendo exportadores e possuindo importantes reservas, os países latino-americanos não garantem desenvolvimento econômico porque o BAIXO VALOR AGREGADO desses produtos não se compara ao dos bens industrializados.","MINERAIS METÁLICOS são recursos NÃO RENOVÁVEIS que possuem em sua composição elementos de metal e possibilitam a condução de calor e eletricidade.","Cerca de 80% de toda a produção mineral latino-americana é enviada para a CHINA e outros países da ÁSIA, segundo a CEPAL — Comissão Econômica para a América Latina e o Caribe, órgão da ONU especializado em questões econômicas latino-americanas.","Destaques mundiais: o CHILE lidera o mercado de COBRE; o MÉXICO é o principal produtor de PRATA do mundo; e o BRASIL é VICE-LÍDER mundial na produção de MINÉRIO DE FERRO.","A CHINA é o principal destino quando se trata de MATÉRIA-PRIMA. Já os ESTADOS UNIDOS são o principal importador de produtos SEMIMANUFATURADOS, isto é, quando a matéria-prima já passou por transformação — e o MÉXICO é o principal exportador desse tipo de produto para eles.","CARVÃO MINERAL: é o combustível fóssil de MAIOR disponibilidade no planeta, e sua qualidade varia conforme a quantidade de carbono e de impurezas. Mesmo depois da adoção do petróleo, continua sendo a SEGUNDA fonte de energia mais consumida no mundo. A participação da América Latina na produção mundial de carvão, porém, é de apenas 0,1%, contra 52,7% da China.","OCDE — Organização para a Cooperação e Desenvolvimento Econômico: 38 países-membros, reúne as economias mais desenvolvidas do mundo e alguns emergentes. Sede em PARIS, sucedendo a Organização para a Cooperação Econômica Europeia, criada em 16 de abril de 1948.","Outro deslize da apostila: ela diz que a OCDE foi fundada em 14 de dezembro de 1961. A convenção que a criou foi assinada em 14 de dezembro de 1960 e entrou em vigor em 30 de setembro de 1961 — é aí que a OCDE nasce.","PETRÓLEO E GÁS: é preciso diferenciar RESERVAS de CAPACIDADE DE PRODUÇÃO. A VENEZUELA tem as maiores reservas de petróleo do mundo, mas NÃO é uma grande produtora: há custos altos de extração e comercialização, e o país sofre com sanções estadunidenses.","Produção de gás natural em 2023 (bilhões de m³): Argentina 41,6 lidera, seguida de México 35,6, Venezuela 29,7, Trinidad e Tobago 25,0 e Brasil 23,4. Em RESERVAS, porém, a Venezuela dispara com 6 300 bilhões de m³.","Na América Latina falta infraestrutura de REFINO, então o petróleo é exportado como matéria-prima, sem transformação — o que diminui o valor agregado.","PROBLEMAS DA MINERAÇÃO: economias com crescimento limitado, vulnerabilidade das exportações, baixo valor agregado, falta de diversificação e impactos ambientais. A exportação quase DUPLICOU nos últimos vinte anos, atrelada à demanda da China e da Ásia.","Além das empresas chinesas, as mineradoras BRITÂNICAS e CANADENSES têm participação importante na região. Muitos países, como o Brasil, FLEXIBILIZARAM leis ambientais para ampliar a atuação das mineradoras.","Conflitos sociais da mineração: expulsão da população local, contaminação das águas e do solo, alteração da fauna e da flora e rompimento de barragens. Os principais conflitos se localizam no MÉXICO, no CHILE e no PERU, seguidos de Argentina, Brasil e Colômbia. Segundo a ONG GLOBAL WITNESS, a América Latina concentra a maior parte dos assassinatos de ambientalistas do mundo."],
      questoes:[
        {p:"A produção mineral pertence a qual setor da economia?", alt:["Setor primário","Setor secundário","Setor terciário","Setor quaternário"], c:0, exp:"Assim como a agricultura: trata-se da extração de recursos da natureza, antes de qualquer transformação industrial."},
        {p:"Por que exportar minérios não garante desenvolvimento econômico aos países latino-americanos?", alt:["Porque o baixo valor agregado não se compara ao dos bens industrializados","Porque as reservas da região são muito pequenas","Porque nenhum país quer comprar esses minérios","Porque a extração é proibida por tratados internacionais"], c:0, exp:"A região tem reservas importantes e exporta bastante — o problema é quanto cada tonelada vale."},
        {p:"O que são minerais metálicos?", alt:["Recursos não renováveis que conduzem calor e eletricidade","Recursos renováveis de origem vegetal","Combustíveis fósseis em estado líquido","Rochas usadas apenas na construção civil"], c:0, exp:"Eles possuem em sua composição elementos químicos e físicos de metal, o que possibilita a condução de calor e eletricidade."},
        {t:"num", p:"Cerca de que porcentagem da produção mineral latino-americana é enviada para a China e outros países da Ásia? (só o número)", r:"80", aceita:["80","80%"], exp:"Cerca de 80%, segundo a Cepal — Comissão Econômica para a América Latina e o Caribe, órgão da ONU."},
        {p:"O que é a Cepal?", alt:["A Comissão Econômica para a América Latina e o Caribe, órgão da ONU","Um bloco econômico sul-americano","Uma empresa mineradora canadense","Uma organização de produtores de petróleo"], c:0, exp:"É o órgão da ONU especializado em questões econômicas latino-americanas."},
        {p:"Qual país latino-americano lidera o mercado mundial de cobre?", alt:["Chile","Brasil","México","Peru"], c:0, exp:"O Chile lidera o cobre, o México é o principal produtor de prata do mundo e o Brasil é vice-líder em minério de ferro."},
        {p:"Qual país latino-americano é o principal produtor de prata do mundo?", alt:["México","Chile","Bolívia","Argentina"], c:0, exp:"O México tem na mineração um dos setores-chave de sua economia."},
        {p:"Qual é a posição do Brasil na produção mundial de minério de ferro?", alt:["Vice-líder mundial","Líder mundial","Quinto colocado","Fora dos dez primeiros"], c:0, exp:"O Brasil é vice-líder mundial na produção de minério de ferro — e o ferro está entre os minerais de maior volume de exportação da região."},
        {p:"Para onde vão os produtos minerais SEMIMANUFATURADOS da América Latina, e qual país mais os exporta?", alt:["Para os Estados Unidos, e o México é o principal exportador","Para a China, e o Brasil é o principal exportador","Para a União Europeia, e o Chile é o principal exportador","Para o Japão, e o Peru é o principal exportador"], c:0, exp:"A China lidera na compra de matéria-prima bruta; os Estados Unidos, na de produtos que já passaram por transformação.", err:{1:"A China é o principal destino da matéria-prima, não dos semimanufaturados."}},
        {p:"Entre os combustíveis fósseis, qual tem a MAIOR disponibilidade no planeta?", alt:["O carvão mineral","O petróleo","O gás natural","O xisto betuminoso"], c:0, exp:"Sua qualidade, porém, varia de acordo com a quantidade de carbono e de impurezas na composição."},
        {p:"Que posição o carvão ocupa hoje entre as fontes de energia mais consumidas no mundo?", alt:["Segunda, atrás do petróleo","Primeira","Quinta","Já não é utilizado"], c:0, exp:"Mesmo com a diminuição do uso após a adoção do petróleo, o carvão continua em segundo lugar."},
        {t:"num", p:"Qual é a participação da América Latina na produção mundial de carvão, em porcentagem? (use vírgula, ex.: 1,5)", r:"0,1", aceita:["0,1","0.1","0,1%"], exp:"Apenas 0,1%, contra 52,7% da China — a participação da região nesse cenário é pouco significativa."},
        {p:"O que é a OCDE?", alt:["Uma organização internacional de 38 países que reúne as economias mais desenvolvidas","Um bloco econômico da América Latina","Uma agência da ONU para o meio ambiente","Uma organização de países exportadores de petróleo"], c:0, exp:"Com sede em Paris, sucedeu a Organização para a Cooperação Econômica Europeia, criada em 1948."},
        {p:"A Venezuela tem as maiores reservas de petróleo do mundo. Por que não é uma grande produtora?", alt:["Pelos altos custos de extração e comercialização, somados às sanções estadunidenses","Porque as reservas estão em território disputado","Porque o país optou por energias renováveis","Porque não há demanda pelo petróleo venezuelano"], c:0, exp:"É a diferença entre ter reservas e ter capacidade de produção — as sanções ainda dificultam o crescimento econômico do país."},
        {p:"Qual país liderou a produção de gás natural na América Latina em 2023?", alt:["Argentina, com 41,6 bilhões de m³","Venezuela, com 29,7 bilhões de m³","Brasil, com 23,4 bilhões de m³","México, com 35,6 bilhões de m³"], c:0, exp:"A Argentina lidera em produção; a Venezuela, em reservas estimadas — 6 300 bilhões de m³, muito à frente de todos.", err:{1:"A Venezuela lidera as reservas, mas aparece em terceiro na produção."}},
        {p:"Por que o petróleo latino-americano é exportado sem passar por transformação?", alt:["Porque falta infraestrutura de refino na região","Porque o refino é proibido por acordos internacionais","Porque o petróleo da região não pode ser refinado","Porque os compradores exigem o produto bruto"], c:0, exp:"Sem refinar, o produto sai como matéria-prima e o valor agregado diminui."},
        {p:"O que impulsionou a quase duplicação das exportações minerais latino-americanas nos últimos vinte anos?", alt:["A crescente demanda da China e do restante da Ásia","A industrialização interna da América Latina","A descoberta de novas reservas na Antártica","A queda do consumo nos Estados Unidos"], c:0, exp:"E o baixo nível de desenvolvimento econômico de muitos países latinos faz com que a exploração ainda dependa de investimento estrangeiro."},
        {p:"Além das chinesas, mineradoras de quais países têm participação importante na região?", alt:["Britânicas e canadenses","Alemãs e japonesas","Russas e indianas","Australianas e coreanas"], c:0, exp:"Apesar da crescente presença das empresas chinesas, as mineradoras britânicas e canadenses mantêm forte atuação."},
        {p:"Que medida muitos países, como o Brasil, tomaram para ampliar a atuação das mineradoras?", alt:["Flexibilizaram leis ambientais","Estatizaram todas as minas","Aumentaram os impostos sobre a extração","Proibiram o capital estrangeiro no setor"], c:0, exp:"Além dos impactos da extração e do beneficiamento, a mineração está envolvida em diversos conflitos sociais."},
        {p:"Em quais países se localizam os principais conflitos envolvendo mineradoras?", alt:["México, Chile e Peru","Brasil, Uruguai e Paraguai","Cuba, Haiti e Jamaica","Venezuela, Guiana e Suriname"], c:0, exp:"Seguidos por Argentina, Brasil e Colômbia. Segundo a ONG Global Witness, a América Latina é a região do mundo onde se concentra a maior parte dos assassinatos de ambientalistas."},
        {p:"Quais são impactos sociais e ambientais associados à mineração, segundo a apostila?", alt:["Expulsão da população local, contaminação de águas e solo e rompimento de barragens","Apenas o aumento do preço dos minérios","Somente a escassez de mão de obra qualificada","A redução do comércio internacional"], c:0, exp:"Há ainda a alteração na fauna e na flora. O documentário 'Minas D'água' (2015), de Danilo Siqueira, retrata esses impactos a partir da exploração de ferro no Brasil."}
      ]},
    { id:"r4", emoji:"🏭", nome:"Rodada 4 — Indústria, maquiladoras e transnacionais",
      desc:"Substituição de importações, o milagre mexicano e o lucro que vai embora.",
      resumo:["Ao longo do século XX as economias latino-americanas se diversificaram e passaram por INDUSTRIALIZAÇÃO, mas o processo NÃO ocorreu de forma igualitária: mesmo dentro de cada país, as indústrias se concentraram em algumas regiões.","As grandes METRÓPOLES concentram as indústrias, enquanto a economia rural predomina nos demais espaços. Mesmo nas metrópoles as desigualdades são acentuadas: apesar da oferta de empregos, boa parte dos trabalhadores não tem renda suficiente para moradia digna e outros bens essenciais.","Os TRÊS PAÍSES MAIS INDUSTRIALIZADOS da América Latina são MÉXICO, BRASIL e ARGENTINA. Participação da indústria no PIB em 2023: México 31,6%, Brasil 22,3%, Argentina 25,1%, Chile 29,7% e Colômbia 24,6% — nessa ordem de VALOR absoluto: México 564,6, Brasil 483,9, Argentina 161,8, Chile 99,5 e Colômbia 89,2 (a tabela diz 'milhões de US$', mas o dado do Banco Mundial está em BILHÕES; a apostila errou a unidade).","DESINDUSTRIALIZAÇÃO NO BRASIL: desde a década de 1970, declínio do investimento estatal e abertura à concorrência com produtos estrangeiros mais baratos e de qualidade superior. Entre os países mais industrializados da região, o Brasil já tem uma das MENORES participações da indústria no PIB, e especialistas projetam estabilização em torno de 20%.","Entraves da industrialização latino-americana: precariedade da infraestrutura de TRANSPORTES, DEFASAGEM TECNOLÓGICA e MERCADO INTERNO RESTRITO, já que parte significativa da população não tem poder aquisitivo. Por isso ela é TARDIA, DESIGUAL e LIMITADA.","SUBSTITUIÇÃO DE IMPORTAÇÕES: modelo típico de países de industrialização tardia, que consiste em criar indústrias nacionais capazes de produzir mercadorias antes importadas. Começa a ganhar destaque na DÉCADA DE 1930, com forte atuação dos Estados, que impuseram BARREIRAS PROTECIONISTAS.","Dois empurrões externos: a CRISE DE 1929, que fragilizou a economia mundial e abriu espaço para que economias agroexportadoras investissem em indústrias; e a SEGUNDA GUERRA MUNDIAL, que dificultou a importação porque a produção estava sendo direcionada aos esforços de guerra. O modelo seguiu sendo adotado até a DÉCADA DE 1970.","MAQUILADORAS (IME — indústrias maquiladoras de exportação): empresas instaladas em território mexicano, fruto de um pacto entre os governos do México e dos Estados Unidos. Iniciado em MAIO DE 1965, com a Política de Industrialização da Fronteira Norte, o acordo buscou dar alternativa aos trabalhadores mexicanos que emigravam para os Estados Unidos.","As maquiladoras fazem apenas a MANUFATURA PARCIAL, a MONTAGEM ou o EMPACOTAMENTO de produtos dos quais NÃO são fabricantes diretos.","A palavra MAQUILA vem do período colonial: era a porção de farinha paga ao dono do moinho em troca da moagem do milho. Na analogia, os Estados Unidos fariam o papel do dono da safra que paga a maquila ao México por utilizar indústrias em seu território.","Essas indústrias, em sua maioria ESTADUNIDENSES, se concentram nas cidades mexicanas de FRONTEIRA, aproveitando mão de obra mais barata e impostos mais baixos: enquanto a média salarial nos Estados Unidos fica entre 20 e 25 dólares por hora, no México cai para 5 dólares por hora.","O primeiro parque industrial, de 1966, foi instalado em CIUDAD JUÁREZ, na fronteira com El Paso (Texas), para montagem de televisores. O segundo foi em NOGALES, fronteira com Tucson (Arizona), para manufatura de plásticos. De 12 empresas e 3 mil empregos em 1965, passou-se a 454 empresas e 67 mil empregos em 1975, e a 3 700 empresas em 2001. A partir de 2003 o modelo entrou em DECLÍNIO, provavelmente pela ascensão da CHINA.","Durante boa parte da década de 1990 as maquiladoras representaram o 'milagre econômico' do México, após seu ingresso no NAFTA (atual USMCA) em 1994. O acordo foi modernizado em 2018 e o USMCA entrou em vigor em 2020. Críticas: exploração do trabalho, realizado principalmente por JOVENS MULHERES mexicanas com salários baixíssimos, impactos ambientais e a volatilidade do modelo.","TRANSNACIONAIS: a partir da DÉCADA DE 1950, indústrias estrangeiras começaram a se instalar na região, sobretudo em Brasil, Argentina e México. Se antes os países centrais exportavam bens industrializados, agora passavam a exportar também CAPITAIS.","Vantagens para as empresas: matérias-primas, energia e mão de obra barata, mercado consumidor significativo e incentivos governamentais (cortes de taxas e impostos). Para os governos: aquecimento da economia e geração de empregos. O problema: os LUCROS das filiais NÃO são reinvestidos no local, sendo enviados em REMESSAS para as sedes."],
      questoes:[
        {p:"Quais são os três países mais industrializados da América Latina?", alt:["México, Brasil e Argentina","Brasil, Chile e Colômbia","México, Venezuela e Cuba","Argentina, Uruguai e Paraguai"], c:0, exp:"Mesmo com participação da indústria no PIB nem sempre superior a 30%, o volume da produção desses três demonstra o tamanho do setor."},
        {p:"Segundo a tabela de 2023, qual país tem a MAIOR participação da indústria no PIB?", alt:["México, com 31,6%","Brasil, com 22,3%","Argentina, com 25,1%","Chile, com 29,7%"], c:0, exp:"E o México também lidera em valor absoluto, à frente do Brasil. (A tabela rotula os valores como milhões de dólares, mas o dado do Banco Mundial está em bilhões — a apostila errou a unidade.)"},
        {p:"O que é a desindustrialização que o Brasil vem sofrendo desde a década de 1970?", alt:["A queda do valor total gerado por atividades industriais","O fechamento obrigatório de fábricas por lei","A mudança das fábricas do campo para a cidade","A troca de máquinas por trabalho manual"], c:0, exp:"Suas causas apontadas são o declínio do investimento estatal nas empresas nacionais e a abertura da concorrência com produtos estrangeiros."},
        {p:"Por que os produtos estrangeiros costumam vencer a concorrência com os nacionais, no caso brasileiro?", alt:["Porque geralmente têm preços menores e qualidade superior","Porque são isentos de qualquer imposto","Porque o governo brasileiro proíbe a produção nacional","Porque os consumidores não conhecem as marcas brasileiras"], c:0, exp:"Especialistas projetam que, se a tendência se mantiver, a atividade industrial brasileira deverá se estabilizar em torno de 20% do PIB."},
        {p:"Quais são os três entraves à industrialização da América Latina citados pela apostila?", alt:["Infraestrutura de transportes precária, defasagem tecnológica e mercado interno restrito","Falta de matérias-primas, excesso de impostos e clima desfavorável","Escassez de energia, de terras e de água","Ausência de portos, de rodovias e de ferrovias"], c:0, exp:"Por isso a industrialização da região é descrita como tardia, desigual e limitada. O mercado interno é restrito porque parte significativa da população não tem poder aquisitivo."},
        {p:"O que é a industrialização por substituição de importações?", alt:["Criar indústrias nacionais capazes de produzir mercadorias antes importadas","Trocar produtos nacionais por importados mais baratos","Importar fábricas inteiras de países desenvolvidos","Substituir trabalhadores por máquinas importadas"], c:0, exp:"É um modelo típico de países de industrialização tardia, como México, Brasil e Argentina."},
        {t:"num", p:"Em que década a industrialização por substituição de importações começou a ganhar destaque na América Latina? (responda com o ano, ex.: 1950)", r:"1930", aceita:["1930","1930s","década de 1930","anos 1930"], exp:"Década de 1930, com forte atuação dos Estados, que impuseram barreiras protecionistas para garantir o desenvolvimento das nascentes indústrias."},
        {p:"Que crise econômica mundial impulsionou as indústrias latino-americanas?", alt:["A crise de 1929","A crise do petróleo de 1973","A crise de 2008","A Grande Depressão de 1870"], c:0, exp:"Ela fragilizou a economia mundial e abriu espaço para que economias essencialmente agroexportadoras, como eram Brasil, Argentina e México, investissem na criação de indústrias."},
        {p:"Como a Segunda Guerra Mundial contribuiu para a industrialização latino-americana?", alt:["Dificultou a importação, pois a produção estrangeira ia para os esforços de guerra","Trouxe fábricas europeias transferidas para a América Latina","Obrigou os países latinos a produzir armamentos","Liberou o comércio entre todos os países"], c:0, exp:"A falta das mercadorias importadas incentivou os capitalistas e os dirigentes a investir na indústria. O modelo seguiu até a década de 1970."},
        {p:"O que fazem as indústrias maquiladoras de exportação (IME)?", alt:["Apenas a manufatura parcial, a montagem ou o empacotamento de produtos","Projetam e fabricam produtos do início ao fim","Extraem e beneficiam minérios","Produzem exclusivamente alimentos para o mercado mexicano"], c:0, exp:"Elas não são fabricantes diretas dos produtos que montam ou empacotam."},
        {t:"num", p:"Em que ano teve início o acordo que criou as maquiladoras, com a Política de Industrialização da Fronteira Norte?", r:"1965", aceita:["1965"], exp:"Maio de 1965 — o acordo buscava dar uma alternativa aos trabalhadores mexicanos que costumavam emigrar para os Estados Unidos em busca de trabalho."},
        {p:"De onde vem a palavra 'maquiladora'?", alt:["De maquila, a porção de farinha paga ao dono do moinho pela moagem do milho","Do nome da primeira empresa instalada em Ciudad Juárez","De uma palavra indígena que significa fronteira","Do verbo espanhol para montar peças"], c:0, exp:"Na analogia com a prática colonial, os Estados Unidos fariam o papel do dono da safra de milho que paga a maquila ao México por utilizar indústrias em seu território."},
        {p:"Por que as maquiladoras se instalaram nas cidades mexicanas de fronteira?", alt:["Pela mão de obra mais barata e pelos impostos mais baixos do México","Porque só lá havia energia elétrica disponível","Porque o governo mexicano proibiu fábricas no interior","Porque a matéria-prima vinha do mar"], c:0, exp:"A média salarial nos Estados Unidos fica entre 20 e 25 dólares por hora; no México, cai para 5 dólares por hora."},
        {p:"Onde foi instalado o primeiro parque industrial maquilador mexicano, em 1966?", alt:["Em Ciudad Juárez, para montagem de televisores","Em Tijuana, para manufatura de plásticos","Em Nogales, para montagem de automóveis","Em Matamoros, para produção de alimentos"], c:0, exp:"O segundo foi em Nogales, fronteira com Tucson (Arizona), para manufatura de plásticos.", err:{2:"Nogales recebeu o segundo parque, e era de plásticos, não de automóveis."}},
        {p:"Que acordo comercial substituiu o Nafta, e quando entrou em vigor?", alt:["O USMCA, em vigor desde 2020","O Mercosul, em vigor desde 1991","A Comunidade Andina, em vigor desde 1969","A OMC, em vigor desde 1994"], c:0, exp:"O Nafta foi modernizado em 2018, dando lugar ao Acordo Estados Unidos-México-Canadá (USMCA), que entrou em vigor em 2020. O México ingressara no Nafta em 1994."},
        {p:"O que provavelmente causou o declínio das maquiladoras a partir de 2003?", alt:["A ascensão da China, com força de trabalho ainda mais barata e boa infraestrutura","O fim do acordo com os Estados Unidos","A falta de trabalhadores no México","Uma proibição ambiental do governo mexicano"], c:0, exp:"O modelo vinha crescendo rápido: de 12 empresas e 3 mil empregos em 1965 para 3 700 empresas em 2001."},
        {p:"Quem realiza principalmente o trabalho nas maquiladoras, segundo as críticas ao modelo?", alt:["Jovens mulheres mexicanas, que recebem salários baixíssimos","Trabalhadores estadunidenses deslocados","Engenheiros estrangeiros altamente qualificados","Apenas trabalhadores temporários de outros países"], c:0, exp:"Além da exploração do trabalho, criticam-se os impactos ambientais e a volatilidade do modelo — é fácil mover uma planta industrial do México para a China."},
        {p:"O que são empresas transnacionais?", alt:["Empresas sediadas em países centrais do capitalismo com filiais em diversos outros países","Empresas estatais que atuam em mais de uma província","Cooperativas formadas por países vizinhos","Empresas que só exportam, sem produzir no exterior"], c:0, exp:"A partir da década de 1950 elas começaram a instalar filiais na América Latina, especialmente em Brasil, Argentina e México."},
        {p:"O que mudou na relação com os países centrais a partir da década de 1950?", alt:["Eles passaram a exportar também capitais, e não só bens industrializados","Eles pararam de comprar produtos primários latino-americanos","Eles transferiram suas sedes para a América Latina","Eles passaram a importar apenas tecnologia da região"], c:0, exp:"Se antes a América Latina exportava produtos primários e importava industrializados, agora recebia investimento direto estrangeiro."},
        {p:"Qual é o principal problema apontado na presença das transnacionais, do ponto de vista dos países que as recebem?", alt:["Os lucros não são reinvestidos no local e são enviados em remessas para as sedes","As empresas não geram nenhum emprego","Elas não pagam nenhum tipo de imposto em lugar algum","Elas só produzem para o mercado interno"], c:0, exp:"Os governos ganham aquecimento da economia e empregos, mas o lucro sai do país."},
        {p:"Que vantagens as empresas estrangeiras encontravam na América Latina?", alt:["Matérias-primas, energia e mão de obra barata, mercado consumidor e incentivos governamentais","Mão de obra altamente especializada e cara","Mercados fechados a qualquer concorrência","Tecnologia mais avançada que a dos países de origem"], c:0, exp:"Os incentivos governamentais incluíam cortes de taxas e impostos."}
      ]},
    { id:"r5", emoji:"🚢", nome:"Rodada 5 — Comércio externo, centro e periferia",
      desc:"Commodities de um lado, chips do outro — e a OMC no meio.",
      resumo:["A DESIGUALDADE é um dos traços característicos do capitalismo: assim como há classes ricas e pobres dentro de uma sociedade, há países que concentram riqueza e países que se mantêm pobres.","Os países do mundo podem ser divididos em DESENVOLVIDOS (ricos, com industrialização mais completa) e SUBDESENVOLVIDOS (pobres, pouco industrializados ou de industrialização tardia). Outra forma de nomear essa divisão é PAÍSES CENTRAIS e PAÍSES PERIFÉRICOS, dentro da DIVISÃO INTERNACIONAL DO TRABALHO (DIT).","A desigualdade entre países centrais e América Latina não começou com a industrialização: muito antes de a Revolução Industrial eclodir na Europa, no SÉCULO XVIII, a EXPLORAÇÃO COLONIAL já produzia essas desigualdades.","Desde os tempos coloniais, a América Latina se integra ao sistema econômico internacional FORNECENDO PRODUTOS PRIMÁRIOS. Depois virou fonte de matérias-primas para a indústria europeia e mercado consumidor para os produtos industrializados da Europa e dos Estados Unidos.","Apesar do avanço da industrialização em alguns países e de iniciativas de cooperação local, a América Latina permanece essencialmente FORNECEDORA DE COMMODITIES e IMPORTADORA de produtos industrializados.","Segundo o Banco Mundial, os QUATRO PRODUTOS MAIS EXPORTADOS pela América Latina são: PETRÓLEO, COBRE, MINÉRIO DE FERRO e SOJA. Os QUATRO MAIS COMPRADOS são: PETRÓLEO REFINADO, CHIPS E CIRCUITOS ELETRÔNICOS, EQUIPAMENTOS DE TELECOMUNICAÇÕES e APARELHOS DE INFORMÁTICA.","Principais parceiros comerciais em 2021: os ESTADOS UNIDOS seguem sendo o principal. Atenção ao sentido da tabela: na coluna IMPORTADOR estão os países que COMPRAM o que a América Latina exporta (EUA 41,95%, China 14,47%); na coluna EXPORTADOR estão os que VENDEM para a região (EUA 30,38%, China 21,41%).","GATT: estabelecido em 1947, numa reunião entre 23 PAÍSES que incluía o Brasil — sigla em inglês para General Agreement on Tariffs and Trade (Acordo Geral de Tarifas e Comércio). Objetivo: promover o comércio internacional reduzindo barreiras e combatendo o protecionismo.","O GATT era PROVISÓRIO e deveria ser substituído pela OMC, prevista na CARTA DE HAVANA, de 1948. Com a recusa dos ESTADOS UNIDOS em ratificar o tratado, a criação da OMC foi adiada e só se efetivou em 1994.","A OMC regula as disparidades ligadas ao PROTECIONISMO, que dificulta a exportação de países que não conseguem concorrer com as tarifas dos produtores locais. Hoje supervisiona aproximadamente US$ 31 TRILHÕES em trocas comerciais.","Nos primeiros 20 anos de funcionamento da OMC, os países da América Latina foram responsáveis por 24% das reclamações registradas, segundo a Cepal.","Quem mais reclama (1995-2024): BRASIL (34), MÉXICO (25) e ARGENTINA (23) — justamente os três países mais industrializados da região. Os principais ALVOS das reclamações são a UNIÃO EUROPEIA (21) e os ESTADOS UNIDOS (18)."],
      questoes:[
        {p:"Como se chamam, na Divisão Internacional do Trabalho, os países ricos e os países pobres?", alt:["Países centrais e países periféricos","Países do Norte e países do Sul","Países ativos e países passivos","Países produtores e países consumidores"], c:0, exp:"É outra forma de se referir à divisão entre desenvolvidos e subdesenvolvidos."},
        {p:"O que caracteriza os países subdesenvolvidos, segundo o texto?", alt:["São pobres e pouco industrializados ou passaram por industrialização tardia","Não possuem recursos naturais","Não participam do comércio internacional","Não têm governo próprio"], c:0, exp:"Os desenvolvidos, por sua vez, reúnem os países mais ricos e que passaram por processos de industrialização mais completa."},
        {p:"A desigualdade entre a América Latina e os países centrais começou quando?", alt:["Na exploração colonial, muito antes da Revolução Industrial","Apenas na década de 1950, com as transnacionais","Somente após a Segunda Guerra Mundial","Com a criação da OMC, em 1994"], c:0, exp:"A Revolução Industrial eclodiu na Europa no século XVIII, mas a exploração colonial já era uma realidade produtora de desigualdades."},
        {p:"Como a América Latina se integrou ao sistema econômico internacional desde os tempos coloniais?", alt:["Fornecendo produtos primários aos países centrais","Exportando tecnologia e máquinas","Financiando a indústria europeia","Recebendo migrantes das colônias asiáticas"], c:0, exp:"Depois, tornou-se fonte de matérias-primas para a indústria europeia e mercado consumidor para os produtos industrializados da Europa e dos Estados Unidos."},
        {p:"Quais são os quatro produtos mais EXPORTADOS pela América Latina?", alt:["Petróleo, cobre, minério de ferro e soja","Chips, celulares, computadores e televisores","Automóveis, aviões, navios e trens","Café, açúcar, algodão e tabaco"], c:0, exp:"São commodities — produtos primários de baixo valor agregado."},
        {p:"E quais são os quatro produtos mais COMPRADOS pela América Latina?", alt:["Petróleo refinado, chips e circuitos eletrônicos, equipamentos de telecomunicações e aparelhos de informática","Soja, milho, carne e café","Minério de ferro, cobre, lítio e prata","Trigo, arroz, feijão e batata"], c:0, exp:"Repare no contraste: a região exporta petróleo cru e importa petróleo refinado — exporta o barato e compra o caro."},
        {p:"Qual continua sendo o principal parceiro comercial da América Latina?", alt:["Estados Unidos","China","União Europeia","Japão"], c:0, exp:"Em 2021 os Estados Unidos compraram 41,95% de tudo o que a América Latina exportou e forneceram 30,38% de tudo o que ela importou — apesar da ascensão da China (14,47% e 21,41%)."},
        {t:"num", p:"Em que ano foi estabelecido o GATT, o Acordo Geral de Tarifas e Comércio?", r:"1947", aceita:["1947"], exp:"1947, numa reunião entre 23 países que incluía o Brasil, com o objetivo de reduzir barreiras e combater o protecionismo."},
        {p:"O que significa a sigla GATT?", alt:["Acordo Geral de Tarifas e Comércio","Grupo de Apoio ao Trabalho e ao Turismo","Garantia Alfandegária de Tarifas Tributárias","Acordo Global de Tratados e Transportes"], c:0, exp:"Do inglês General Agreement on Tariffs and Trade."},
        {p:"Por que a criação da Organização Mundial do Comércio foi adiada?", alt:["Pela recusa dos Estados Unidos em ratificar o tratado","Porque nenhum país se interessou pela proposta","Porque a Segunda Guerra Mundial ainda não havia terminado","Porque a ONU vetou a organização"], c:0, exp:"Ela constava na Carta de Havana, de 1948, mas só se efetivou em 1994."},
        {t:"num", p:"Em que ano a OMC foi efetivamente criada?", r:"1994", aceita:["1994"], exp:"1994 — quase cinquenta anos depois de ter sido prevista na Carta de Havana, de 1948."},
        {p:"O que a OMC busca regular?", alt:["As disparidades econômicas ligadas ao protecionismo","O preço internacional do petróleo","A migração de trabalhadores entre países","As emissões de carbono das indústrias"], c:0, exp:"O protecionismo dificulta a exportação de países que não conseguem concorrer com as tarifas dos produtores locais. A OMC supervisiona aproximadamente US$ 31 trilhões em trocas comerciais."},
        {p:"Que porcentagem das reclamações registradas na OMC, nos seus primeiros 20 anos, veio de países da América Latina?", alt:["24%","5%","50%","72%"], c:0, exp:"Segundo a Cepal — os países latino-americanos estão entre os que mais buscam a OMC para resolver problemas de barreiras protecionistas."},
        {p:"Quais países latino-americanos mais acionaram a OMC entre 1995 e 2024?", alt:["Brasil, México e Argentina","Chile, Peru e Colômbia","Cuba, Venezuela e Bolívia","Uruguai, Paraguai e Equador"], c:0, exp:"Brasil com 34 reclamações, México com 25 e Argentina com 23 — justamente os três países mais industrializados da região."},
        {p:"Quem são os principais ALVOS das reclamações registradas por países latino-americanos na OMC?", alt:["A União Europeia e os Estados Unidos","A China e a Índia","O Japão e a Coreia do Sul","A Rússia e o Canadá"], c:0, exp:"A União Europeia aparece com 21 queixas e os Estados Unidos com 18, bem à frente dos demais."},
        {p:"Por que existem diferenças nos lucros entre países que exportam commodities e os que exportam tecnologia?", alt:["Por causa do valor agregado ao produto","Porque as commodities não têm mercado","Porque a tecnologia é mais barata de produzir","Porque os países pobres exportam mais volume"], c:0, exp:"O crescimento das trocas comerciais não atinge todos os países da mesma forma, por causa da concentração de produção, das relações que se estabelecem e do valor agregado."}
      ]},
    { id:"r6", emoji:"🤝", nome:"Rodada relâmpago — blocos econômicos e paraísos fiscais",
      desc:"Mercosul, Comunidade Andina e o dinheiro que some em offshores.",
      resumo:["BLOCOS ECONÔMICOS são grupos de países que buscam melhorar o comércio regional e ganhar inserção no mercado internacional, fazendo frente às filiais de transnacionais de países ricos. Eles incentivam intercâmbios tecnológicos, facilitam o acesso a matérias-primas e fortalecem as negociações comerciais.","Os dois blocos mais importantes da América Latina são o MERCOSUL e a COMUNIDADE ANDINA.","MERCOSUL — Mercado Comum do Sul, principal bloco econômico da América do Sul. Membros: BRASIL, ARGENTINA, PARAGUAI e URUGUAI. Criado pela assinatura do TRATADO DE ASSUNÇÃO, em MARÇO DE 1991, na capital paraguaia, com o objetivo de construir um mercado comum a partir de dezembro de 1994.","Objetivos do Tratado de Assunção: aumentar a COMPETITIVIDADE econômica dos quatro países no cenário internacional; aumentar a produtividade e intensificar os FLUXOS DE COMÉRCIO com o resto do mundo, atraindo investimentos; e promover a ABERTURA ECONÔMICA dos países-membros, demarcando a atuação do setor privado.","A VENEZUELA foi aceita como membro pleno em 2012, mas teve sua participação SUSPENSA por tempo indeterminado em 2016. A BOLÍVIA foi aceita como membro pleno em 2015, MAS até 2021 ainda era considerada Estado associado, porque seguia em processo de adesão. São membros ASSOCIADOS, sem poder de voto: Chile, Colômbia, Equador, Guiana, Peru e Suriname. O MÉXICO participa como país OBSERVADOR.","O Mercosul é considerado uma UNIÃO ADUANEIRA IMPERFEITA: apesar das reduções de tarifas, muitos produtos dos países-membros ainda enfrentam barreiras, o que impede caracterizá-lo como zona de livre circulação plena. A maior dificuldade são as DISPARIDADES ECONÔMICAS entre os membros, entre os quais o BRASIL se destaca.","Principais parceiros comerciais do Mercosul: CHINA, ESTADOS UNIDOS e UNIÃO EUROPEIA. Em 2022 a CHINA foi o principal destino das exportações (25%), seguida da União Europeia (16%) e dos Estados Unidos (11%); e foi também a principal origem das importações (25%).","O Mercosul exporta principalmente SOJA, PETRÓLEO CRU, MINÉRIO DE FERRO e MILHO. Importa principalmente COMBUSTÍVEIS, FERTILIZANTES, DEFENSIVOS AGRÍCOLAS e MEDICAMENTOS.","COMUNIDADE ANDINA (CAN): inicialmente chamada PACTO ANDINO, criada pelo ACORDO DE CARTAGENA, em 1969 — uma das experiências de integração mais ANTIGAS da América Latina. O objetivo principal era formar uma UNIÃO ADUANEIRA, com tarifas alfandegárias comuns, e seguir uma política de substituição de importação em escala regional.","Membros iniciais da CAN segundo a apostila: Chile, Bolívia, Colômbia e Peru — mas o Acordo de Cartagena foi assinado por CINCO países, e a apostila esquece o EQUADOR (por isso ele aparece depois entre os permanentes sem que se explique quando entrou). A Venezuela ingressou em 1973 e saiu em 2006; o Chile saiu em 1976. Membros permanentes hoje: BOLÍVIA, COLÔMBIA, EQUADOR e PERU. Associados: Argentina, Brasil, Chile, Paraguai e Uruguai. Observadores: ESPANHA e MARROCOS.","Objetivos da CAN: integração comercial, econômica e política entre os membros; promover os países do bloco no cenário econômico mundial; e reduzir as diferenças de desenvolvimento econômico e social entre os países-membros.","PARAÍSOS FISCAIS são países ou regiões que facilitam a abertura de empresas com tributos BAIXOS ou ISENTOS e cujas instituições financeiras garantem o SIGILO BANCÁRIO, protegendo a identidade dos correntistas. Quem transfere fortunas para lá deixa de pagar impostos no país de origem e escapa das fiscalizações.","Os paraísos fiscais também servem à LAVAGEM DE DINHEIRO: ganhos de tráfico de drogas, contrabando de armas, fraudes e corrupção são enviados a bancos e empresas sediados fora do país de origem do investidor, as OFFSHORES, e de lá voltam a ser usados em operações legais.","Muitos paraísos fiscais ficam em pequenos países da AMÉRICA CENTRAL e do CARIBE: Bahamas, Bermudas, Costa Rica, Ilhas Cayman e Ilhas Virgens Britânicas. Mais de 25% das fortunas privadas da América Latina estão em paraísos fiscais, o que faz da região a MAIOR FONTE de fortunas em offshores de todo o mundo."],
      questoes:[
        {p:"Para que servem os blocos econômicos?", alt:["Melhorar o comércio regional e ganhar inserção no mercado internacional","Impedir qualquer comércio com países de fora","Unificar os governos dos países-membros","Substituir as moedas nacionais por uma única moeda mundial"], c:0, exp:"Eles incentivam intercâmbios tecnológicos, facilitam o acesso a matérias-primas e fortalecem as negociações comerciais, fazendo frente às transnacionais de países ricos."},
        {p:"Quais são os quatro países-membros plenos fundadores do Mercosul?", alt:["Brasil, Argentina, Paraguai e Uruguai","Brasil, Argentina, Chile e Uruguai","Brasil, Venezuela, Paraguai e Bolívia","Argentina, Chile, Peru e Uruguai"], c:0, exp:"O Chile foi convidado já em 1990, mas se mantém apenas como associado até hoje."},
        {t:"num", p:"Em que ano foi assinado o Tratado de Assunção, que criou o Mercosul?", r:"1991", aceita:["1991"], exp:"Março de 1991, na capital paraguaia — com o objetivo de construir um mercado comum a partir de dezembro de 1994."},
        {p:"Em que cidade foi assinado o tratado que criou o Mercosul?", alt:["Assunção, capital do Paraguai","Buenos Aires, capital da Argentina","Montevidéu, capital do Uruguai","Brasília, capital do Brasil"], c:0, exp:"Daí o nome Tratado de Assunção."},
        {p:"Qual destes NÃO era um objetivo do Tratado de Assunção?", alt:["Criar um exército comum para os países-membros","Aumentar a competitividade econômica dos quatro países","Intensificar os fluxos de comércio com o resto do mundo","Promover a abertura econômica dos países-membros"], c:0, exp:"Os objetivos eram econômicos e comerciais — inclusive demarcar a atuação do setor privado —, não militares."},
        {p:"O que aconteceu com a participação da Venezuela no Mercosul?", alt:["Foi aceita como membro pleno em 2012 e suspensa por tempo indeterminado em 2016","Nunca chegou a ser aceita no bloco","É membro pleno desde a fundação","Participa apenas como país observador"], c:0, exp:"O documento de suspensão cita descumprimentos de regras internas, mas a própria adesão havia ocorrido entre polêmicas e divergências políticas."},
        {p:"Qual país participa do Mercosul como OBSERVADOR?", alt:["México","Chile","Bolívia","Peru"], c:0, exp:"Chile, Colômbia, Equador, Guiana, Peru e Suriname são associados, sem poder de voto; o México é observador. A Bolívia foi aceita como membro pleno em 2015, mas até 2021 ainda constava como Estado associado, em processo de adesão."},
        {p:"Por que o Mercosul é considerado uma união aduaneira IMPERFEITA?", alt:["Porque muitos produtos dos membros ainda enfrentam barreiras para circular no bloco","Porque nem todos os membros pagam suas contribuições","Porque o bloco não tem sede fixa","Porque a moeda ainda não foi unificada"], c:0, exp:"Apesar das reduções significativas de tarifas, não há zona de livre circulação de mercadorias plena. A maior dificuldade são as disparidades econômicas entre os membros, entre os quais o Brasil se destaca."},
        {p:"Qual foi o principal destino das exportações do Mercosul em 2022?", alt:["China, com 25%","União Europeia, com 16%","Estados Unidos, com 11%","Chile, com 4%"], c:0, exp:"A China lidera tanto as exportações quanto as importações do bloco, com 25% em ambas."},
        {p:"Quais são os principais produtos exportados pelo Mercosul?", alt:["Soja, petróleo cru, minério de ferro e milho","Medicamentos, fertilizantes e defensivos agrícolas","Automóveis, chips e celulares","Café, cacau e algodão"], c:0, exp:"E os mais importados são combustíveis, fertilizantes, defensivos agrícolas e medicamentos — o mesmo padrão de exportar primário e importar industrializado.", err:{1:"Esses são justamente os produtos que o bloco COMPRA, não os que vende."}},
        {p:"Como a Comunidade Andina se chamava inicialmente?", alt:["Pacto Andino","União Aduaneira do Pacífico","Acordo de Lima","Comunidade dos Andes"], c:0, exp:"O nome mudou depois da assinatura do Acordo de Cartagena, em 1969."},
        {t:"num", p:"Em que ano foi assinado o Acordo de Cartagena, que deu origem à Comunidade Andina?", r:"1969", aceita:["1969"], exp:"1969 — é uma das experiências de integração mais antigas da América Latina, bem anterior ao Mercosul."},
        {p:"Qual era o principal objetivo original do Acordo de Cartagena?", alt:["Formar uma união aduaneira, com tarifas alfandegárias comuns entre os membros","Criar uma moeda única para os Andes","Construir uma ferrovia ligando os países andinos","Formar uma aliança militar contra os Estados Unidos"], c:0, exp:"Num primeiro momento, o bloco buscava também seguir uma política econômica de substituição de importação em escala regional."},
        {p:"Quais são hoje os membros PERMANENTES da Comunidade Andina?", alt:["Bolívia, Colômbia, Equador e Peru","Chile, Bolívia, Colômbia e Peru","Venezuela, Colômbia, Equador e Peru","Argentina, Brasil, Chile e Uruguai"], c:0, exp:"O Chile deixou o pacto em 1976 e a Venezuela, em 2006 — ela havia ingressado em 1973.", err:{1:"Essa é a lista de fundadores que a apostila traz — e o Chile saiu em 1976. (Na verdade o Acordo de Cartagena teve cinco signatários: faltou o Equador nessa lista.)"}},
        {p:"Quais países são observadores da Comunidade Andina?", alt:["Espanha e Marrocos","Estados Unidos e Canadá","China e Japão","Portugal e França"], c:0, exp:"Argentina, Brasil, Chile, Paraguai e Uruguai são países associados do bloco."},
        {p:"O que é um paraíso fiscal?", alt:["Um país ou região com tributos baixos ou isentos e sigilo bancário garantido","Um país que não cobra imposto de seus próprios cidadãos","Uma região protegida por acordos ambientais","Uma zona franca de comércio dentro de um país"], c:0, exp:"As instituições financeiras protegem a identidade dos correntistas, e quem transfere fortunas para lá deixa de contribuir com impostos no país de origem."},
        {p:"O que são offshores?", alt:["Bancos e empresas com sede fora do país de origem do investidor","Plataformas de extração de petróleo em alto-mar","Navios que transportam commodities","Fábricas instaladas em zonas de fronteira"], c:0, exp:"Geralmente instaladas em paraísos fiscais, elas permitem que ganhos de origem ilegal voltem a ser usados em operações legais — é a lavagem de dinheiro."},
        {p:"Que tipos de ganhos ilegais costumam passar pelos paraísos fiscais?", alt:["Tráfico de drogas, contrabando de armas, fraudes em empresas e corrupção","Apenas sonegação de impostos de pequenas empresas","Somente lucros de operações na bolsa de valores","Exclusivamente heranças não declaradas"], c:0, exp:"Por isso os paraísos fiscais são frequentemente associados à lavagem de dinheiro."},
        {p:"Onde se localizam muitos dos paraísos fiscais citados pela apostila?", alt:["Em pequenos países da América Central e do Caribe","Nos países escandinavos","No leste da Ásia","Na África subsaariana"], c:0, exp:"Bahamas, Bermudas, Costa Rica, Ilhas Cayman e Ilhas Virgens Britânicas estão entre os exemplos."},
        {t:"num", p:"Mais de que porcentagem das fortunas privadas da América Latina está em paraísos fiscais? (só o número)", r:"25", aceita:["25","25%"], exp:"Mais de 25% — o que faz da região a maior fonte de fortunas em offshores de todo o mundo."}
      ]}
  ]});
